import __manifest__


def _get_manifest():
    """Load and evaluate the manifest dict from the module source."""
    with open(__manifest__.__file__) as f:
        return eval(f.read())


def test_data_contains_views_file():
    manifest = _get_manifest()
    assert 'views/issue_analysis_views.xml' in manifest['data']


def test_data_contains_automation_file():
    manifest = _get_manifest()
    assert 'data/automation.xml' in manifest['data']


def test_data_has_two_entries():
    manifest = _get_manifest()
    assert len(manifest['data']) == 2


def test_manifest_name():
    manifest = _get_manifest()
    assert manifest['name'] == 'AI Issue Analysis'
